const fs        = require('fs');
const path      = require('path');

const ASSETS  = __dirname;
const FINAL   = path.resolve(ASSETS, '..', '..', 'Final');
const PNG_DIR = path.join(FINAL, 'PNG');
const SVG_DIR = path.join(FINAL, 'SVG');

[FINAL, PNG_DIR, SVG_DIR].forEach(d => fs.mkdirSync(d, { recursive: true }));

