// ── Export manifest ──────────────────────────────────────────────────────────
// bg: null = transparent PNG  |  bg: '#hex' = solid background
const EXPORTS = [
  // Wordmark — Full Color (transparent, on white in production)
  { file: 'Logo_Full_Color.svg',      out: 'Wordmark_Color_2x',           w: 1240, h: 280,  bg: null        },
  { file: 'Logo_Full_Color.svg',      out: 'Wordmark_Color_3x',           w: 1860, h: 420,  bg: null        },
  // Wordmark — White (transparent; place on dark backgrounds)
  { file: 'Logo_White.svg',           out: 'Wordmark_White_2x',           w: 1240, h: 280,  bg: null        },
  { file: 'Logo_White.svg',           out: 'Wordmark_White_3x',           w: 1860, h: 420,  bg: null        },
  // Wordmark — Mono Black (transparent)
  { file: 'Logo_Mono_Black.svg',      out: 'Wordmark_Mono_Black_2x',      w: 1240, h: 280,  bg: null        },
  { file: 'Logo_Mono_Black.svg',      out: 'Wordmark_Mono_Black_3x',      w: 1860, h: 420,  bg: null        },
  // Wordmark — Mono White (transparent; place on dark backgrounds)
  { file: 'Logo_Mono_White.svg',      out: 'Wordmark_Mono_White_2x',      w: 1240, h: 280,  bg: null        },
  { file: 'Logo_Mono_White.svg',      out: 'Wordmark_Mono_White_3x',      w: 1860, h: 420,  bg: null        },
  // Icon — Color, transparent
  { file: 'Logo_Icon_Only.svg',       out: 'Icon_Color_280px',            w: 280,  h: 280,  bg: null        },
  { file: 'Logo_Icon_Only.svg',       out: 'Icon_Color_400px',            w: 400,  h: 400,  bg: null        },
  // Icon — Color, Emerald background (social media profile photo)
  { file: 'Logo_Icon_Only.svg',       out: 'Icon_Social_400px',           w: 400,  h: 400,  bg: '#1B4D3E', pad: 56 },
  // Icon — Mono Black, transparent
  { file: 'Logo_Icon_Mono_Black.svg', out: 'Icon_Mono_Black_280px',       w: 280,  h: 280,  bg: null        },
  // Favicons
  { file: 'Logo_Icon_Only.svg',       out: 'Favicon_32px',                w: 32,   h: 32,   bg: null        },
  { file: 'Logo_Icon_Only.svg',       out: 'Favicon_192px',               w: 192,  h: 192,  bg: null        },
  // Apple Touch Icon — solid Emerald background (iOS home screen)
  { file: 'Logo_Icon_Only.svg',       out: 'Apple_Touch_Icon_180px',      w: 180,  h: 180,  bg: '#1B4D3E', pad: 24 },
];

// ── HTML wrapper builder ─────────────────────────────────────────────────────
function buildHTML(svgRaw, w, h, bg, pad = 0) {
  const iconW = w - pad * 2;
  const iconH = h - pad * 2;

  // Override the SVG's own width/height so it fills the target dimensions
  let svg = svgRaw
    .replace(/(<svg[^>]*)\swidth="[^"]*"/, `$1 width="${pad ? iconW : w}"`)
    .replace(/(<svg[^>]*)\sheight="[^"]*"/, `$1 height="${pad ? iconH : h}"`);

  const bodyStyle = [
    'margin:0', 'padding:0', 'box-sizing:border-box',
    `width:${w}px`, `height:${h}px`,
    'overflow:hidden', 'display:flex',
    'align-items:center', 'justify-content:center',
    bg ? `background:${bg}` : ''
  ].filter(Boolean).join(';');

  return `<!DOCTYPE html><html><head><meta charset="UTF-8">${FONTS}
<style>*{margin:0;padding:0;box-sizing:border-box}
html,body{${bodyStyle}}
svg{display:block;flex-shrink:0}</style>
</head><body>${svg}</body></html>`;
}

// ── Main ─────────────────────────────────────────────────────────────────────
(async () => {
  console.log('\n── Alinaya Logo PNG Exporter ──────────────────────────────');
  console.log(`   Output: ${PNG_DIR}\n`);

  const browser = await puppeteer.launch({
    headless: true,
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-web-security']
  });
  const page = await browser.newPage();

  for (const e of EXPORTS) {
    const svgRaw  = fs.readFileSync(path.join(ASSETS, e.file), 'utf8');
    const html    = buildHTML(svgRaw, e.w, e.h, e.bg || null, e.pad || 0);
    const outFile = path.join(PNG_DIR, `${e.out}.png`);

    await page.setViewport({ width: e.w, height: e.h, deviceScaleFactor: 1 });
    await page.setContent(html, { waitUntil: 'domcontentloaded', timeout: 10000 });
    await page.evaluate(() => document.fonts.ready);
    await new Promise(r => setTimeout(r, 200));

    await page.screenshot({
      path: outFile,
      omitBackground: !e.bg,
      clip: { x: 0, y: 0, width: e.w, height: e.h }
    });

    console.log(`   ✓ ${e.out}.png  (${e.w}×${e.h}${e.bg ? ', ' + e.bg + ' bg' : ', transparent'})`);
  }

  await browser.close();

  // ── Copy fixed SVG sources into Final/SVG/ ──────────────────────────────
  const SVG_FILES = [
    'Logo_Full_Color.svg',
    'Logo_White.svg',
    'Logo_Icon_Only.svg',
    'Logo_Mono_Black.svg',
    'Logo_Mono_White.svg',
    'Logo_Icon_Mono_Black.svg',
    'Logo_Master_Source.svg',
  ];

  console.log('');
  for (const f of SVG_FILES) {
    const src = path.join(ASSETS, f);
    const dst = path.join(SVG_DIR, f);
    if (fs.existsSync(src)) {
      fs.copyFileSync(src, dst);
      console.log(`   ✓ SVG copied: ${f}`);
    }
  }

  console.log(`\n── Complete: ${EXPORTS.length} PNGs + ${SVG_FILES.filter(f => fs.existsSync(path.join(ASSETS, f))).length} SVGs ──\n`);
})().catch(err => {
  console.error('\nError:', err.message);
  process.exit(1);
});
